void read_cutscene_knobs(const fs::path& build) noexcept {
    try {
        std::error_code ignored;
        cutscene_knob_off=fs::exists(build/L"no-vr-cutscenes",ignored);
        cutscene_no_bink=fs::exists(build/L"no-bink-theater",ignored);cutscene_no_skip_hold=fs::exists(build/L"no-cutscene-skip-hold",ignored);cutscene_no_letterbox_hide=fs::exists(build/L"no-letterbox-hide",ignored);
        std::string text;{std::ifstream knob(build/L"cutscene-mode");if(knob) std::getline(knob,text);}
        const auto parsed=d2vr::parse_cutscene_mode(text);
        cutscene_mode_override=parsed?static_cast<int>(*parsed):-1;
    } catch(...) {}
}
void refresh_cutscene_knobs(UINT64 now,bool cinematic) {
    if(cinematic && !cutscene_knob_cinematic) cutscene_knob_tick=0; // the cinematic bit just appeared: re-read now
    cutscene_knob_cinematic=cinematic;
    if(!cinematic) return; // Ruling 15: no worker thread in gameplay (StartProbe reads once; the bit's arrival re-reads at once)
    if(cutscene_knob_tick && now>=cutscene_knob_tick && now-cutscene_knob_tick<500u) return;
    if(cutscene_knob_reading.exchange(true)) return; // the previous read is still running
    cutscene_knob_tick=now?now:1;
    try {std::thread([build=output_directory.always().parent_path()/L"build"] {read_cutscene_knobs(build);cutscene_knob_reading=false;}).detach();}
    catch(...) {cutscene_knob_reading=false;}
}
