static d2vr::HandBodyProbeRunner hand_body_probe_runner;   // B7: read-only hand-body research probe (build/hand-body-probe; one set per second, at most 120)
// B11: the hand-body creation spike (build/hand-body-spike, content R1/R2/R3, read once at start, logged to hand-body-spike.txt; sim only).
// Absent knob: nothing is installed (no hook, no counter, no thread). It needs NativeGrab's 0x89fb0 hook (its tick runs there).
static std::uintptr_t hand_body_camera() {
    auto camera=camera_address;
    if(!camera || !d2vr::native_player_camera(read_self,image_base,camera)) camera=native_grab.last_published_camera();
    return camera;
}
static void start_hand_body_spike(const fs::path& root,const fs::path& output) {
    std::string text;{std::ifstream knob(root/L"build"/L"hand-body-spike");std::getline(knob,text,'\0');}
    std::ofstream note(output/L"hand-body-spike.txt",std::ios::trunc);
    note<<"knob build/hand-body-spike read once: \""<<text.substr(0,64)<<"\"\n";
    const auto route=d2vr::parse_spike_route(text);
    if(!route) {note<<"invalid route (expected R1, R2 or R3): spike off\n";return;}
    if(!native_grab.enabled()) {note<<"physical grab (the 0x89fb0 hook) is not installed: spike off\n";return;}
    std::string why;
    const bool ok=d2vr::HandBodySpikeEngine::install(image_base,&read_self,&game_logic_mask,&hand_body_camera,*route,output,why);
    note<<"route "<<d2vr::spike_route_name(*route)<<(ok?": installed":": off")<<(why.empty()?"":" - ")<<why<<'\n';
}
// B13: the production hand body (build/hand-body and no build/no-hand-body; default off until B17), knobs read once per session start, logged
// to hand-body.txt. It never runs with the spike knob (they share the count-only hooks). Absent knob: nothing is installed (no hook, no
// thread, no engine call), the release gate is not consulted and the input path is untouched; status says {"enabled":false}.
static std::atomic<bool> hand_body_requested{false};
static void start_hand_body(const fs::path& root,const fs::path& output) {
    std::ofstream note(output/L"hand-body.txt",std::ios::trunc);
    note<<"knobs read once: build/hand-body present, build/no-hand-body absent\n";
    if(fs::exists(root/L"build"/L"hand-body-spike")) {note<<"build/hand-body-spike exists (the spike owns the shared hooks): hand body off\n";
        d2vr::HandBodyRuntime::note_install_failure("build/hand-body-spike exists");hand_body_requested=false;return;}
    if(!native_grab.enabled()) {note<<"physical grab (the 0x89fb0 hook) is not installed: hand body off\n";
        d2vr::HandBodyRuntime::note_install_failure("physical grab (the 0x89fb0 hook) is not installed");hand_body_requested=false;return;}
    std::string why;
    d2vr::HandBodyRuntime::legacy_stuck(fs::exists(root/L"build"/L"legacy-hand-stuck"));   // v639: a body wedged 1 s away from a blocked target is released (re-created when free)
    const bool ok=d2vr::HandBodyRuntime::install(image_base,&read_self,&game_logic_mask,&hand_body_camera,output,why);
    note<<(ok?"installed":"off")<<(why.empty()?"":" - ")<<why<<'\n';
    if(!ok) hand_body_requested=false;
}
static d2vr::HandBodyProbeRunner::Sample hand_body_probe_sample(std::uint64_t tick) {
    d2vr::HandBodyProbeRunner::Sample sample;
    // The camera: the config's address, or (if that does not resolve) the one NativeGrab's publishers hold. A diag row records both.
    std::uintptr_t camera_used=camera_address,published_camera=0;
    published_camera=native_grab.last_published_camera();   // an atomic: the probe never takes NativeGrab's mutex
    if(!camera_used || !d2vr::native_player_camera(read_self,image_base,camera_used)) if(published_camera) camera_used=published_camera;
    {d2vr::BodyProbeRow diag;diag.tick=tick;diag.what="diag_camera_sources";diag.userdata=camera_address;diag.userdata_plus8=published_camera;diag.entity=camera_used;sample.rows.push_back(diag);}
    {auto bodies=d2vr::probe_player_bodies(read_self,image_base,tick,camera_used);sample.rows.insert(sample.rows.end(),bodies.begin(),bodies.end());}
    sample.render_thread=gpu_render_thread.load(std::memory_order_acquire);   // the thread the GPU hooks were bound on (the present/render thread), for the G1 thread comparison
    const auto game=d2vr::rig::value<std::uintptr_t>(read_self,image_base+0x39a5290);
    const auto world=game?d2vr::rig::value<std::uintptr_t>(read_self,*game+0x60410):std::nullopt;
    if(world) sample.world_filter_vtable_rva=d2vr::world_filter_vtable_rva(read_self,image_base,*world);
    if(const auto camera=d2vr::native_player_camera(read_self,image_base,camera_used)) {   // the nearest loose prop within 2 m of the player, if any
        const d2vr::Vec3 point{camera->aim_origin[0],camera->aim_origin[1],camera->aim_origin[2]};
        if(const auto prop=d2vr::probe_nearby_prop(read_self,image_base,point,2.0))
            if(const auto row=d2vr::probe_prop_userdata(read_self,image_base,*prop,tick)) sample.rows.push_back(*row);
    }
    return sample;
}
