        if(!(in>>x>>y>>ms) || (in>>extra) || !std::isfinite(x) || !std::isfinite(y) ||
           std::abs(x)>1 || std::abs(y)>1 || !ms || ms>5000)return "usage: move <x[-1,1]> <y[-1,1]> <ms[1,5000]>";
        test_move_x=x;test_move_y=y;test_move_until=GetTickCount64()+ms;
